/* Type definition related to watchdog registers */
typedef struct
{
  uint32 WDG_PROT;       /* Watchdog protection register */
  uint32 dummy1;
  uint32 WDG_CNT;        /* Watchdog counter register */
  uint32 WDG_RSTCAUSE;   /* Watchdog reset cause register */
  uint32 WDG_TRG0;       /* Watchdog trigger0 register */
  uint32 dummy2;
  uint32 WDG_TRG1;       /* Watchdog trigger1 register */
  uint32 dummy3;
  uint32 WDG_INT;        /* Watchdog interruption configuration register */
  uint32 WDG_INTCLR;     /* Watchdog interruption clear register */
  uint32 dummy4;
  uint32 WDG_TRG0CFG;    /* Watchdog trigger0 configuration register */
  uint32 WDG_TRG1CFG;    /* Watchdog trigger1 configuration register */
  uint32 WDG_RUNLLS;     /* Watchdog lower limit RUN setting register */
  uint32 WDG_RUNULS;     /* Watchdog upper limit RUN setting register */
  uint32 WDG_PSSLLS;     /* Watchdog lower limit PSS setting register */
  uint32 WDG_PSSULS;     /* Watchdog upper limit PSS setting register */
  uint32 WDG_RSTDLY;     /* Watchdog delay counter register */
  uint32 WDG_CFG;        /* Watchdog configuration register */
  uint32 WDG_RUNLLC;     /* Watchdog lower limit RUN current register */
  uint32 WDG_RUNULC;     /* Watchdog upwer limit RUN current register */
  uint32 WDG_PSSLLC;     /* Watchdog lower limit PSS current register */
  uint32 WDG_PSSULC;     /* Watchdog upper limit PSS current register */
}
Wdg_66_IA_RegsType;

/* Type definition related to interruption control registers */
typedef struct
{
  volatile uint32 * const WDG_IRC0_UNLOCK;
  volatile uint32 * const WDG_IRC0_CSR;
  volatile uint32 * const WDG_IRC0_IRQHC;
  volatile uint32 * const WDG_IRC0_NMIHC;
}
Wdg_66_IA_IRCRegsType;

